input.newString:
/* Clock model: the night runs 12 AM -> 6 AM. Each in-game hour lasts
   HOUR_SECONDS, and minutes/seconds sweep smoothly inside that hour.
   Everything (HUD, tablet, game-over stats) reads from these helpers so
   the displays can never drift apart again. */
clockParts() {
  const clamped = Math.max(0, this.nightT);
  const hIdx = Math.min(5, Math.floor(clamped / HOUR_SECONDS));
  const hourProgress = (clamped % HOUR_SECONDS) / HOUR_SECONDS;
  // 12 AM is hour 0; after the first hour it becomes 1 AM.
  const hour24 = (hIdx + 12) % 12;
  const hourLabel = hIdx === 0 ? '12' : String(hIdx);
  const totalSeconds = Math.floor(hourProgress * 3600);
  const minute = Math.floor(totalSeconds / 60) % 60;
  const second = totalSeconds % 60;
  return { hIdx, hour24, hourLabel, minute, second, hourProgress };
}
displayHour() {
  return this.clockParts().hourLabel;
}
clockString(withSeconds = false) {
  const c = this.clockParts();
  const mm = String(c.minute).padStart(2, '0');
  const ss = String(c.second).padStart(2, '0');
  return withSeconds
    ? `${c.hourLabel}:${mm}:${ss} AM`
    : `${c.hourLabel}:${mm} AM`;
}
hourIndex() { return Math.min(5, Math.floor(this.nightT / HOUR_SECONDS)); }

